draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // umbrella
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // umbrella handle
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // rain
  for (let i = 0; i < 20; i++) {
    ctx.beginPath();
    ctx.moveTo(Math.random() * W, -50 + Math.sin(t + i) * 200);
    ctx.lineTo(Math.random() * W, -50 + Math.sin(t + i) * 200 + 20);
    ctx.stroke();
  }

  // rain drops under umbrella
  for (let i = 0; i < 10; i++) {
    if (Math.random() > 0.5) {
      ctx.beginPath();
      ctx.moveTo(W/2 + Math.sin(t + i) * 40, H/2 + 50 + Math.cos(t + i) * 40);
      ctx.lineTo(W/2 + Math.sin(t + i) * 40, H/2 + 50 + Math.cos(t + i) * 40 + 10);
      ctx.stroke();
    }
  }

  ctx.restore();
}
